        _check_time(body["end"], "end")
        if body["start"] > body["end"]:
            raise ValueError("start must not be after end")
    except ValueError:
        return _invalid_request()
    if H is None:
        return _history_unavailable()
    try:
        bundle = H.audit_bundle(record_ids, body["start"], body["end"])
    except KeyError:
