@pytest.mark.parametrize(
    "body",
    [
        b"{not json",
        b"[]",
        b'"x"',
        b"null",
        b"{}",
        b'{"before": {}}',
        b'{"before": {}, "after": {}, "extra": 1}',
        b'{"earlier": {}, "later": {}}',
    ],
)
def test_http_bad_body_is_422(body):
