    # Main before: [a: X]
    return bind([{"id": "a", "proof": _x()}])


@functools.lru_cache(maxsize=1)
def _b2():
    # Main after: a changed X->Y, b added with X.
    return bind(
        [
            {"id": "a", "proof": _y()},
            {"id": "b", "proof": _x()},
        ]
    )


@functools.lru_cache(maxsize=1)
def _b3():
    # Two shared members [a: X, b: Y].
